class Solution { public int maxResult(int[] nums,int k){int[] dp=new int[nums.length];dp[0]=nums[0];Deque<Integer> deque=new ArrayDeque<>();deque.offerLast(0);for(int i=1;i<nums.length;i++){while(deque.peekFirst()<i-k)deque.pollFirst();dp[i]=nums[i]+dp[deque.peekFirst()];while(!deque.isEmpty()&&dp[deque.peekLast()]<=dp[i])deque.pollLast();deque.offerLast(i);}return dp[nums.length-1];} }
